// Copies the repository's reference docs into the site's content collection, so docs/ stays the
// one place they are written:
//
//   docs/dsl.md            → reference/dsl
//   docs/diadraw.grammar   → reference/grammar
//   docs/libraries.md      → reference/libraries
//   docs/guide/*.md        → reference/guide/* (the guide's README becomes its index)
//   docs/credits.md        → credits (generated by tools/gen/credits.mjs; English only)
//
// Each page gets Starlight frontmatter (its title from the first heading, which is dropped),
// links between these docs are rewritten to the site's pages, links to anything else in the
// repository point at it on GitHub, and untagged code blocks are highlighted as DiaDraw.

import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, posix, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const site = fileURLToPath(new URL('..', import.meta.url));
const root = join(site, '..');
const content = join(site, 'src/content/docs');
const blob = 'https://github.com/mykulyak/diadraw/blob/main/';

/** Repository path (posix) → site slug under reference/. */
const pages = new Map([
  ['docs/dsl.md', 'reference/dsl'],
  ['docs/diadraw.grammar', 'reference/grammar'],
  ['docs/libraries.md', 'reference/libraries'],
  ['docs/credits.md', 'credits'],
]);
/** Pages that stay in English in every locale, and where to edit what they are made from. */
const untranslated = new Map([['docs/credits.md', 'tools/credits/components.json']]);
const guide = readdirSync(join(root, 'docs/guide'))
  .filter((f) => f.endsWith('.md'))
  .sort();
for (const file of guide) {
  const name = file === 'README.md' ? 'index' : file.slice(0, -3);
  pages.set(`docs/guide/${file}`, name === 'index' ? 'reference/guide' : `reference/guide/${name}`);
}
// The guide's own order, as its README lists the chapters.
const order = [
  ...readFileSync(join(root, 'docs/guide/README.md'), 'utf8').matchAll(/\]\(([\w-]+)\.md\)/g),
].map((m) => m[1]);

/** A link from the page at `fromSlug` to `toSlug`, relative so it works under any base. */
function pageLink(fromSlug, toSlug, hash) {
  const rel = posix.relative(fromSlug, toSlug);
  return `${rel === '' ? './' : `${rel}/`}${hash}`;
}

function rewriteLinks(text, source, slug) {
  return text.replace(/\]\(([^)\s]+)\)/g, (whole, target) => {
    if (/^[a-z]+:/i.test(target) || target.startsWith('#')) return whole;
    const [path, hash = ''] = target.split(/(?=#)/);
    const resolved = posix.normalize(posix.join(posix.dirname(source), path));
    const page = pages.get(resolved);
    if (page) return `](${pageLink(slug, page, hash)})`;
    return `](${blob}${resolved}${hash})`;
  });
}

/** Untagged fences are DiaDraw source, except the informal grammar (it has `:=`). */
function tagFences(text) {
  return text.replace(/^```([^\n]*)\n([\s\S]*?)^```$/gm, (whole, language, body) =>
    language ? whole : '```' + (body.includes(':=') ? 'text' : 'diadraw') + '\n' + body + '```',
  );
}

/** YAML frontmatter from plain values and one level of nested objects (JSON is valid YAML). */
function frontmatter(fields) {
  return Object.entries(fields)
    .map(([key, value]) =>
      typeof value === 'object'
        ? `${key}:\n${Object.entries(value)
            .map(([k, v]) => `  ${k}: ${JSON.stringify(v)}`)
            .join('\n')}`
        : `${key}: ${JSON.stringify(value)}`,
    )
    .join('\n');
}

function write(out, slug, title, body, extra = {}) {
  const index = slug === 'reference/guide' ? '/index' : '';
  const file = join(out, `${slug}${index}.md`);
  mkdirSync(dirname(file), { recursive: true });
  const notice =
    "<!-- Generated by site/scripts/sync-docs.mjs; edit the source in the repository's docs/. -->";
  writeFileSync(
    file,
    `---\n${frontmatter({ title, ...extra })}\n---\n\n${notice}\n\n${body.trimStart()}`,
  );
}

function markdownPage(out, source, canonical, slug, extra) {
  const text = readFileSync(join(root, source), 'utf8');
  const match = /^# (.+)\n/m.exec(text);
  if (!match) throw new Error(`${source}: no top-level heading`);
  const body = text.slice(match.index + match[0].length);
  // Translations use the English tree's relative links, including links to shared repo files.
  write(out, slug, match[1].trim(), tagFences(rewriteLinks(body, canonical, slug)), {
    editUrl: `https://github.com/mykulyak/diadraw/edit/main/${source}`,
    ...extra,
  });
}

const grammar = readFileSync(join(root, 'docs/diadraw.grammar'), 'utf8');
const lezer = '[Lezer](https://lezer.codemirror.net/)';
const dsl = pageLink('reference/grammar', 'reference/dsl', '');
const locales = {
  '': {
    introduction: 'Introduction',
    title: 'Grammar',
    description: `The DSL's grammar in ${lezer} notation. It is a reference: the
core parses with a hand-written, error-tolerant parser that builds the tree this grammar
describes, with the same node names. The [DSL reference](${dsl})
explains each construct.`,
  },
  pl: {
    introduction: 'Wprowadzenie',
    title: 'Gramatyka',
    description: `Gramatyka DSL w notacji ${lezer} służy jako dokumentacja. Rdzeń używa ręcznie napisanego parsera odpornego na błędy, który tworzy opisane tu drzewo z tymi samymi nazwami węzłów. [Dokumentacja DSL](${dsl}) objaśnia każdą konstrukcję.`,
  },
  uk: {
    introduction: 'Вступ',
    title: 'Граматика',
    description: `Граматику DSL подано в нотації ${lezer} для довідки. Ядро використовує написаний вручну синтаксичний аналізатор, стійкий до помилок. Він будує описане тут дерево з тими самими назвами вузлів. Кожну конструкцію пояснено в [довіднику DSL](${dsl}).`,
  },
  fr: {
    introduction: 'Introduction',
    title: 'Grammaire',
    description: `La grammaire du DSL en notation ${lezer} sert de référence. Le cœur utilise un analyseur écrit à la main qui tolère les erreurs et construit l’arbre décrit ici, avec les mêmes noms de nœuds. Le [manuel de référence du DSL](${dsl}) explique chaque construction.`,
  },
  de: {
    introduction: 'Einführung',
    title: 'Grammatik',
    description: `Die DSL-Grammatik in ${lezer}-Notation dient als Referenz. Der Kern verwendet einen handgeschriebenen, fehlertoleranten Parser, der den hier beschriebenen Baum mit denselben Knotennamen erzeugt. Die [DSL-Referenz](${dsl}) erläutert jedes Sprachkonstrukt.`,
  },
};

for (const [locale, { introduction, title, description }] of Object.entries(locales)) {
  const out = join(content, locale);
  const guideOut = join(out, 'reference/guide');
  mkdirSync(guideOut, { recursive: true });
  for (const file of readdirSync(guideOut, { withFileTypes: true })) {
    if (file.isFile() && file.name.endsWith('.md')) rmSync(join(guideOut, file.name));
  }
  for (const [canonical, slug] of pages) {
    if (canonical.endsWith('.grammar')) continue;
    const translated = locale ? canonical.replace('docs/', `docs/i18n/${locale}/`) : canonical;
    // A page not translated yet falls back to English, so a new chapter never breaks the build.
    const source = existsSync(join(root, translated)) ? translated : canonical;
    if (source !== translated && !untranslated.has(canonical)) {
      console.warn(`sync-docs: ${translated} is missing; using ${canonical} for ${locale}`);
    }
    const position = order.indexOf(posix.basename(slug));
    const sidebar =
      slug === 'reference/guide'
        ? { sidebar: { order: 0, label: introduction } }
        : slug.startsWith('reference/guide/')
          ? { sidebar: { order: position < 0 ? 99 : position + 1 } }
          : {};
    const edit = untranslated.get(canonical);
    markdownPage(out, source, canonical, slug, {
      ...sidebar,
      ...(edit ? { editUrl: `https://github.com/mykulyak/diadraw/edit/main/${edit}` } : {}),
    });
  }

  write(
    out,
    'reference/grammar',
    title,
    `${description}\n\n\`\`\`text title="docs/diadraw.grammar"\n${grammar.trimEnd()}\n\`\`\`\n`,
    {
      editUrl: 'https://github.com/mykulyak/diadraw/edit/main/docs/diadraw.grammar',
    },
  );
  console.log(`sync-docs: ${pages.size} pages into ${relative(site, out)}/reference/`);
}
